// Drift guard: apps/web/src/data/{cities,krakow,chrome}.ts are generated by
// `pnpm gen:content` from content/{seed,chrome}.json. This test fails if
// someone hand-edits the generated TS without regenerating — the seed is
// the only way in.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { chrome } from "./chrome";
import { cities } from "./cities";
import { krakowStories } from "./krakow";

const dbDir = fileURLToPath(new URL("../../../../content", import.meta.url));
const seed = JSON.parse(readFileSync(`${dbDir}/seed.json`, "utf8"));
const seededChrome = JSON.parse(readFileSync(`${dbDir}/chrome.json`, "utf8"));

describe("generated data files", () => {
  it("cities.ts matches content/seed.json", () => {
    expect(cities).toEqual(seed.cities);
  });

  it("krakow.ts matches the krakow stories in seed.json", () => {
    const krakowSeed = seed.stories.filter(
      (story: { cityId: string }) => story.cityId === "krakow",
    );
    expect(krakowStories).toEqual(krakowSeed);
  });

  it("chrome.ts matches content/chrome.json", () => {
    expect(chrome).toEqual(seededChrome);
  });
});
